/// <reference types="vite/client" />

/** Generated by the image-manifest plugin in vite.config.ts from the files under public/images. */
declare module 'virtual:image-manifest' {
  const manifest: {
    /** Every picture, as a path relative to public/ (e.g. "images/items/weapons/spear.png"). */
    files: string[];
    /** "<folder>/<file name without extension>" -> path of the preferred file. */
    byId: Record<string, string>;
  };
  export default manifest;
}
